import{_ as i,o as a,c as t,ae as r}from"./chunks/framework.C4zpkcTP.js";const p=JSON.parse('{"title":"Security notes","description":"","frontmatter":{},"headers":[],"relativePath":"security.md","filePath":"security.md"}'),o={name:"security.md"};function n(s,e,l,d,c,u){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="security-notes" tabindex="-1">Security notes <a class="header-anchor" href="#security-notes" aria-label="Permalink to &quot;Security notes&quot;">​</a></h1><h2 id="development-is-not-production" tabindex="-1">Development is not production <a class="header-anchor" href="#development-is-not-production" aria-label="Permalink to &quot;Development is not production&quot;">​</a></h2><p>The development Compose file and example passwords are <strong>not production deployment instructions</strong>.</p><h2 id="what-a-production-install-needs" tabindex="-1">What a production install needs <a class="header-anchor" href="#what-a-production-install-needs" aria-label="Permalink to &quot;What a production install needs&quot;">​</a></h2><ul><li>externally provisioned PostgreSQL,</li><li>unique high-entropy secrets for <code>SESSION_SECRET</code> and <code>MCP_TOKEN_SECRET</code>,</li><li>HTTPS,</li><li>secure secret management,</li><li>reviewed network and firewall policy,</li><li>regular database backups.</li></ul><h2 id="boundaries-to-keep-in-mind" tabindex="-1">Boundaries to keep in mind <a class="header-anchor" href="#boundaries-to-keep-in-mind" aria-label="Permalink to &quot;Boundaries to keep in mind&quot;">​</a></h2><ul><li>Never expose PostgreSQL or Docker sockets to a public interface.</li><li>Never put a production secret in browser code, a checked-in <code>.env</code>, a Docker image, logs, or the agent registration UI.</li><li>Reverse-proxy trust is disabled by default. Configure and review that boundary before deploying behind a proxy.</li><li>Authentication and request validation do not replace TLS.</li></ul><h2 id="mcp-specific-guidance" tabindex="-1">MCP-specific guidance <a class="header-anchor" href="#mcp-specific-guidance" aria-label="Permalink to &quot;MCP-specific guidance&quot;">​</a></h2><p>The MCP endpoint is a network-reachable, credential-authenticated interface.</p><ul><li>Treat each AI credential as a production secret.</li><li>Grant the lowest permission level that works.</li><li>Prefer expiries for temporary agents.</li><li>Revoke credentials you no longer use.</li><li>Keep <code>MCP_ENABLED=false</code> on instances where no agent should connect.</li></ul><h2 id="secret-storage" tabindex="-1">Secret storage <a class="header-anchor" href="#secret-storage" aria-label="Permalink to &quot;Secret storage&quot;">​</a></h2><ul><li>Passwords are stored as Argon2id hashes.</li><li>Session tokens are stored only as keyed digests.</li><li>AI credential tokens are stored only as HMAC-SHA256 digests.</li><li>The raw AI token is returned once and never stored or returned again.</li></ul><h2 id="session-behavior" tabindex="-1">Session behavior <a class="header-anchor" href="#session-behavior" aria-label="Permalink to &quot;Session behavior&quot;">​</a></h2><ul><li>Sessions are server-side and revocable.</li><li>Cookies are HttpOnly and SameSite.</li><li>Cookies are Secure in production.</li><li>Sessions have a fixed expiry.</li></ul><h2 id="api-boundaries" tabindex="-1">API boundaries <a class="header-anchor" href="#api-boundaries" aria-label="Permalink to &quot;API boundaries&quot;">​</a></h2><ul><li>The browser API trusts the exact configured Origin.</li><li>Cookie-authenticated mutations without that Origin are rejected.</li><li>There is no reflected wildcard CORS by default.</li><li>Request sizes, security headers, and generic credential errors are enforced at the API boundary.</li></ul><h2 id="audit-integrity" tabindex="-1">Audit integrity <a class="header-anchor" href="#audit-integrity" aria-label="Permalink to &quot;Audit integrity&quot;">​</a></h2><ul><li><code>audit_logs</code> is append-only at the database level.</li><li>No application path can rewrite or erase audit history.</li><li>Sensitive values are redacted before storage.</li></ul>',18)])])}const b=i(o,[["render",n]]);export{p as __pageData,b as default};
